def calculate_a(n):
    a = [0] * (n + 1)
    a[1] = 0
    for k in range(2, n + 1):
        max_val = -1
        for i in range(1, k):
            # a_k = max_{1 <= i <= k - 1} {a_i + a_{k - i} + min(i, k - i)}
            current_val = a[i] + a[k - i] + min(i, k - i)
            if current_val > max_val:
                max_val = current_val
        a[k] = max_val
    return a[1:]

# Calculate up to n=8
sequence = calculate_a(8)
print("Sequence values a_1 through a_8:")
for i, val in enumerate(sequence):
    print(f"a_{i+1} = {val}")

