def compute_a(n, memo):
    if n in memo:
        return memo[n]
    if n == 1:
        return 0

    if n % 2 == 0:
        # Even case: a_n = 2*a_{n/2} + n/2
        # Assuming maximization holds at i = n/2
        result = 2 * compute_a(n // 2, memo) + n // 2
    else:
        # Odd case: a_n = a_{(n-1)/2} + a_{(n+1)/2} + (n-1)/2
        # Assuming maximization holds at i = (n-1)/2 or i = (n+1)/2
        k = (n - 1) // 2
        result = compute_a(k, memo) + compute_a(k + 1, memo) + k

    memo[n] = result
    return result

# Calculate a_2025
memo = {}
a_2025 = compute_a(2025, memo)
print(f"a_2025 = {a_2025}")
